mapper.select:
select m.*, tm.`id` as tenant_menu_id from sys_menu as m left join sys_tenant_user_menu as tum on tum.menu_id = m.id left join sys_tenant_menu as tm on tm.menu_id = m.id
m.status = 1
and tum.tenant_id=#{tenantId}
and tum.tenant_member_id=#{tenantMemberId}

select m.*, tm.`id` as tenant_menu_id from sys_tenant_menu as tm left join sys_menu as m on tm.menu_id = m.id
and m.id=#{menuId}
limit 1
